fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Extract the three (index, value) pairs.
    let mut trio = vec![
        (i, valores[i]),
        (j, valores[j]),
        (k, valores[k]),
    ];

    // Sort them in descending order by value.
    trio.sort_by(|a, b| b.1.cmp(&a.1));

    // Return the two indices whose values are the highest,
    // in non-increasing order of their values.
    (trio[0].0, trio[1].0)
}

